def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    ones=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==1]
    # Draw the diagonal line segment between the two 1 markers.
    if len(ones)>=2:
        (r1,c1),(r2,c2)=ones[0],ones[1]
        dr=1 if r2>r1 else -1; dc=1 if c2>c1 else -1
        for k in range(min(abs(r2-r1),abs(c2-c1))+1):
            rr,cc=r1+k*dr,c1+k*dc
            if grid[rr][cc]!=6: out[rr][cc]=1
    # Each 6 extends along both diagonals to the grid boundary.
    for r in range(h):
        for c in range(w):
            if grid[r][c]==6:
                for d in (-1,1):
                    rr,cc=r+d,c+d
                    while 0<=rr<h and 0<=cc<w:
                        if grid[rr][cc] not in (1,6): out[rr][cc]=6
                        rr+=d;cc+=d
                    rr,cc=r+d,c-d
                    while 0<=rr<h and 0<=cc<w:
                        if grid[rr][cc] not in (1,6): out[rr][cc]=6
                        rr+=d;cc-=d
    return out
